_native_facts=r.native_facts
def native_facts(c):
 if c['artwork_id']!=NATIVE_TITLE_REVIEW['artwork_id']:return _native_facts(c)
 import copy
 if c['title']!=NATIVE_TITLE_REVIEW['catalogue_title'] or c['museum_page']!=NATIVE_TITLE_REVIEW['museum_page']:raise ValueError('Individual native-title concordance scope differs')
 adapted=copy.deepcopy(c);adapted['title']=NATIVE_TITLE_REVIEW['native_title'];facts=_native_facts(adapted)
 if facts['accession']!=NATIVE_TITLE_REVIEW['native_accession'] or facts['period']!=NATIVE_TITLE_REVIEW['native_period']:raise ValueError('Individual native-title object evidence differs')
 facts['individual_native_title_concordance']=NATIVE_TITLE_REVIEW
 return facts
r.native_facts=native_facts
